ALTER TABLE "League" ADD COLUMN "provider" TEXT NOT NULL DEFAULT 'MANUAL', ADD COLUMN "externalId" TEXT, ADD COLUMN "season" INTEGER NOT NULL DEFAULT 2026, ADD COLUMN "previousLeagueId" TEXT;
ALTER TABLE "Draft" ADD COLUMN "userSlot" INTEGER, ADD COLUMN "rounds" INTEGER NOT NULL DEFAULT 16, ADD COLUMN "lastSyncedAt" TIMESTAMP(3), ADD COLUMN "syncError" TEXT;
ALTER TABLE "DraftPick" ADD COLUMN "externalId" TEXT, ADD COLUMN "slot" INTEGER, ADD COLUMN "isKeeper" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "source" TEXT NOT NULL DEFAULT 'MANUAL';
CREATE UNIQUE INDEX "League_provider_externalId_season_key" ON "League"("provider","externalId","season");
CREATE UNIQUE INDEX "Draft_platform_externalId_key" ON "Draft"("platform","externalId");
CREATE UNIQUE INDEX "DraftPick_draftId_externalId_key" ON "DraftPick"("draftId","externalId");
CREATE TABLE "Manager" ("id" TEXT NOT NULL,"provider" TEXT NOT NULL,"externalId" TEXT NOT NULL,"displayName" TEXT NOT NULL,"avatarUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Manager_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Manager_provider_externalId_key" ON "Manager"("provider","externalId");
CREATE TABLE "LeagueMember" ("id" TEXT NOT NULL,"leagueId" TEXT NOT NULL,"managerId" TEXT NOT NULL,"externalTeamId" TEXT NOT NULL,"teamName" TEXT NOT NULL,"draftSlot" INTEGER,"isUser" BOOLEAN NOT NULL DEFAULT false,"tendency" JSONB,"sampleSize" INTEGER NOT NULL DEFAULT 0,"confidence" DOUBLE PRECISION NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "LeagueMember_pkey" PRIMARY KEY ("id"),CONSTRAINT "LeagueMember_leagueId_fkey" FOREIGN KEY ("leagueId") REFERENCES "League"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "LeagueMember_managerId_fkey" FOREIGN KEY ("managerId") REFERENCES "Manager"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "LeagueMember_leagueId_managerId_key" ON "LeagueMember"("leagueId","managerId");
CREATE INDEX "LeagueMember_managerId_idx" ON "LeagueMember"("managerId");
CREATE TABLE "LeagueSync" ("id" TEXT NOT NULL,"leagueId" TEXT NOT NULL,"provider" TEXT NOT NULL,"status" TEXT NOT NULL,"records" INTEGER NOT NULL DEFAULT 0,"error" TEXT,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),CONSTRAINT "LeagueSync_pkey" PRIMARY KEY ("id"),CONSTRAINT "LeagueSync_leagueId_fkey" FOREIGN KEY ("leagueId") REFERENCES "League"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "LeagueSync_leagueId_startedAt_idx" ON "LeagueSync"("leagueId","startedAt");
